function outcomeLines(out) {
    if (!out) return [];
    if (out.skipped) {
        return ['⏭️ merge backstop skipped on PR #' + out.prNumber + ' (' + out.skipped + ')'];
    }
    if (!out.counted.length) return [cleanOutcomeLine(out)];
    return [countedOutcomeLine(out)];
}

