    'default': {
        BLOCKING: { round: 'rework', fix: 'mandatory' },
        IMPORTANT: { round: 'rework', fix: 'mandatory' },
        SUGGESTION: { round: 'polish', fix: 'mandatory' },
        NIT: { round: 'none', fix: 'opportunistic' }
